import{_ as t,o,c as a,ae as n}from"./chunks/framework.Dn6zxbF8.js";const u=JSON.parse('{"title":"Annotations and Transient Annotations","description":"","frontmatter":{"id":"5177934677","title":"Annotations and Transient Annotations","state":"Approved","created":"2026-06-28T00:00:00.000Z","tags":["annotations","metadata","event-sourcing","eda"],"category":"Platform"},"headers":[],"relativePath":"adrs/5177934677/README.md","filePath":"adrs/5177934677/README.md"}'),i={name:"adrs/5177934677/README.md"};function r(s,e,d,l,c,h){return o(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="annotations-and-transient-annotations" tabindex="-1">Annotations and Transient Annotations <a class="header-anchor" href="#annotations-and-transient-annotations" aria-label="Permalink to &quot;Annotations and Transient Annotations&quot;">​</a></h1><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Records that move through our systems (events, commands, requests, projections, resources) need a place to carry caller-attached metadata that the platform itself does not interpret. Examples of the <em>shape</em> of need (not an enumeration of keys) include: cross-cutting observability context, write-time plumbing, caller-owned domain tags, and platform cross-cutting concerns that are not first-class envelope fields.</p><p>Two questions have to be answered consistently across every record type:</p><ol><li><strong>Who owns which keys</strong>, so callers from different systems and teams can attach metadata without colliding.</li><li><strong>How long does an attached entry live</strong>, so storage knows what to persist, and projections know what to copy onto downstream resources.</li></ol><p>Existing precedents were considered:</p><ul><li>Kubernetes splits metadata into <code>labels</code> (selectable, indexed) and <code>annotations</code> (opaque, free-form). The split exists because the API server is the selector engine and has to index a bounded namespace cheaply, and because selector values need bounded, matchable syntax. The split earns its keep exactly where such an engine exists. This ADR does not assume one: it governs the opaque namespace. A system that does operate a selector engine (resolving routing or binding selectors against metadata) <code>MAY</code> add a separate selectable field for those keys as a downstream decision; that field is out of this ADR&#39;s scope and does not change the rules here.</li><li>CloudEvents, NATS headers, Kafka headers, AMQP application properties, and HTTP headers all use a single flat map with a reserved-prefix convention.</li><li>Event-sourced systems consistently distinguish between metadata that is part of the event&#39;s permanent record and metadata that is attached only for the moment of delivery (tracing context, idempotency, retry plumbing). This distinction maps to real, irreversible system behaviors (persistence and projection), and is decided by the caller at write time.</li></ul><p>The axis that earns its keep in our environment is <strong>lifetime</strong>, not selectability.</p><p>This ADR defines only the <strong>specification</strong> of the annotation namespace. It does not enumerate which keys exist, where any particular concern (tracing, idempotency, correlation, etc.) should be placed, or how individual projections behave. Those are caller and consumer decisions applied using this specification. First-class envelope fields (record identifiers, types, timestamps, schema versions, causation, aggregate identity, and similar platform-interpreted fields) are out of scope and are governed elsewhere.</p><h2 id="resolution" tabindex="-1">Resolution <a class="header-anchor" href="#resolution" aria-label="Permalink to &quot;Resolution&quot;">​</a></h2><p>Written records (events, commands, requests) expose two sibling fields with identical shape and identical key rules, distinguished only by lifetime. Resources and projections expose only the first; they never carry a <code>transient_annotations</code> field (see Lifetime contract):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>annotations:           { &lt;key&gt;: &lt;string&gt;, ... }</span></span>
<span class="line"><span>transient_annotations: { &lt;key&gt;: &lt;string&gt;, ... }   # written records only</span></span></code></pre></div><h3 id="shape" tabindex="-1">Shape <a class="header-anchor" href="#shape" aria-label="Permalink to &quot;Shape&quot;">​</a></h3><ul><li>Both fields are maps of string key to string value.</li><li>Values are <strong>opaque to the platform</strong>. The platform does not parse, validate, or interpret values. Callers that need structured values <code>MUST</code> encode them as strings (for example, JSON-encoded).</li><li>Annotation values <code>MUST NOT</code> use typed dynamic containers such as <code>map&lt;string, google.protobuf.Value&gt;</code>, <code>google.protobuf.Struct</code>, or equivalent open-ended JSON value maps as the platform contract. Typed domain data belongs in first-class fields or separately governed schemas.</li><li>Both fields are optional. Absence and an empty map are equivalent.</li><li>Caller-attached opaque metadata <code>MUST</code> live in these two fields. Records <code>MUST NOT</code> grow parallel ad-hoc fields for the same purpose.</li><li>This specification defines no size or count limits. Systems <code>MAY</code> impose documented limits, and propagating consumers <code>MAY</code> filter entries to stay within them.</li></ul><h3 id="key-syntax" tabindex="-1">Key syntax <a class="header-anchor" href="#key-syntax" aria-label="Permalink to &quot;Key syntax&quot;">​</a></h3><p>Keys follow the Kubernetes label key syntax, by reference:</p><ul><li>A key is either <code>&lt;name&gt;</code> or <code>&lt;prefix&gt;/&lt;name&gt;</code>.</li><li><code>&lt;prefix&gt;</code>, when present, <code>MUST</code> be a DNS subdomain (lowercase alphanumerics, <code>-</code>, and <code>.</code>; segments separated by <code>.</code>; total length <code>&lt;= 253</code> characters).</li><li><code>&lt;name&gt;</code> <code>MUST</code> be <code>1..63</code> characters, beginning and ending with an alphanumeric, with <code>-</code>, <code>_</code>, and <code>.</code> permitted in between.</li></ul><h3 id="ownership-and-reservation" tabindex="-1">Ownership and reservation <a class="header-anchor" href="#ownership-and-reservation" aria-label="Permalink to &quot;Ownership and reservation&quot;">​</a></h3><ul><li>A prefix <code>MUST</code> be a DNS subdomain owned by the writer.</li><li>Unprefixed keys belong to the caller&#39;s own namespace and <code>MUST NOT</code> be written by the platform.</li><li>Keys under a platform-owned prefix are reserved for that platform. Consumers <code>MUST NOT</code> write to a prefix they do not own.</li><li><code>trogondb.com/</code> is reserved for TrogonDB platform-written annotations. Callers <code>MUST NOT</code> write keys under this prefix unless they are acting as the platform component that owns the key.</li><li>Additional reserved prefixes <code>MUST</code> be documented by the system that owns them before they are used.</li><li>Ownership governs authorship: creating, modifying, or removing an entry. Carrying an existing entry forward verbatim during propagation is not authorship and is permitted for keys the propagator does not own.</li></ul><h3 id="prefix-identity-and-stability" tabindex="-1">Prefix identity and stability <a class="header-anchor" href="#prefix-identity-and-stability" aria-label="Permalink to &quot;Prefix identity and stability&quot;">​</a></h3><p>A prefix is an opaque identifier that borrows DNS syntax for decentralized uniqueness. It is not a live pointer to a DNS record:</p><ul><li>A prefix does not need to resolve. Ownership is established when the prefix is first documented, per the reservation rules above, not by holding the DNS registration.</li><li>Teams do not need their own domain. Ownership delegates the way DNS does: a team <code>MAY</code> mint a prefix under a domain its organization owns (for example, <code>payments.example.com/</code>).</li><li>Once a key under a prefix has been written, the prefix is permanent. Renaming, losing, or selling the domain later does not transfer or invalidate the prefix, and registering a lapsed domain grants no claim over keys already documented by another writer.</li><li>Because persisted records are immutable, writers <code>SHOULD</code> mint prefixes on the most stable name available, such as a product or system name rather than corporate branding. Migrating to a new prefix means writing new keys going forward; keys under the old prefix remain valid in persisted records forever and <code>MUST NOT</code> be rewritten.</li></ul><h3 id="lifetime-contract" tabindex="-1">Lifetime contract <a class="header-anchor" href="#lifetime-contract" aria-label="Permalink to &quot;Lifetime contract&quot;">​</a></h3><p>An <strong>operation</strong> is a single logical write performed in response to one processing occasion, such as handling one command, one consumed delivery, or one API request, regardless of how many records or streams it writes to.</p><ul><li><code>annotations</code><ul><li><code>MUST</code> be persisted as part of the record&#39;s permanent representation when the record is persisted.</li><li>Follow the mutability of the record they are attached to: immutable on immutable records such as events, updatable on mutable records such as resources, subject to the ownership rules above.</li><li><code>SHOULD</code> be projected onto downstream resources by default. Projectors <code>MAY</code> filter on a per-rule basis.</li></ul></li><li><code>transient_annotations</code><ul><li>Are attached at write time for the lifetime of the delivery.</li><li>Describe the operation, not an individual record: an operation that writes multiple records <code>MUST</code> attach the same entries to every record it writes.</li><li><code>MUST NOT</code> be projected onto downstream resources. This is absolute, not a default: the field does not exist on resources.</li><li><code>MAY</code> be persisted alongside the record for replay and audit purposes. Persistence <code>MAY</code> be opted out of per stream or per system when the cost is not justified; the default is to persist.</li><li>Are best-effort context. Because persistence can be opted out and propagation can filter, consumers <code>MUST NOT</code> depend on an entry being present for correctness.</li></ul></li><li>Resources and projections <code>MUST NOT</code> expose a <code>transient_annotations</code> field.</li></ul><h3 id="propagation" tabindex="-1">Propagation <a class="header-anchor" href="#propagation" aria-label="Permalink to &quot;Propagation&quot;">​</a></h3><p>Projection and propagation are distinct behaviors. Projection copies metadata from a record onto a downstream resource (a read model), and is governed by the lifetime contract above. Propagation copies metadata from an incoming record onto the new records emitted as a result of processing it, such as a workflow consuming an event and writing the events that result from it.</p><p>The two fields have opposite defaults:</p><ul><li><code>annotations</code> describe the record they are attached to and do not propagate by default. The writer of a resulting record <code>MAY</code> copy an entry forward when the fact it records is also true of the new record.</li><li><code>transient_annotations</code> travel with the write path. A consumer that emits records as a result of processing an incoming record <code>SHOULD</code> propagate the incoming <code>transient_annotations</code> onto all of the records the resulting operation emits, not a chosen subset, so that context spanning a causation chain (for example, correlating the deliveries of a workflow end to end) survives every hop without becoming part of any record&#39;s projected representation. Consumers <code>MAY</code> filter or add entries when propagating, subject to the ownership rules above; filtering is per entry and applies uniformly across the operation&#39;s resulting records.</li></ul><p>Key collisions during propagation resolve as follows:</p><ul><li>When an operation processes multiple incoming records whose <code>transient_annotations</code> conflict on a key, the consumer <code>MUST</code> resolve the conflict deterministically. Dropping the conflicting key is the safe default; a wrong value is worse than an absent one.</li><li>When a propagated entry collides with an entry the consumer attaches itself, the consumer&#39;s own entry wins: the author of the operation outranks inherited context.</li><li>Propagation carries unprefixed keys across writer boundaries, where they can collide with another writer&#39;s unprefixed keys. Callers that need collision-free keys across a chain <code>SHOULD</code> use a prefix.</li></ul><p>Propagation terminates where projection begins: resources never expose transient annotations, regardless of how many hops an entry traveled.</p><h3 id="choosing-between-the-two" tabindex="-1">Choosing between the two <a class="header-anchor" href="#choosing-between-the-two" aria-label="Permalink to &quot;Choosing between the two&quot;">​</a></h3><p>The writer decides at attach time:</p><ul><li>If the entry is a fact about the record that should remain true forever, it belongs in <code>annotations</code>.</li><li>If the entry is meaningful only for the delivery and processing of the record, it belongs in <code>transient_annotations</code>. Transient does not mean single-hop: an entry can propagate across an entire processing chain (see Propagation) and still never surface on a resource.</li></ul><p>This decision is local to the writer and does not require coordination with consumers.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>Every record type answers &quot;where does caller metadata go?&quot; the same way, and a reader checks exactly two fields to find it.</li><li>Correlating a causation chain end to end works without polluting any resource&#39;s projected representation, because propagation and projection have opposite defaults.</li><li>Prefix ownership makes cross-team key collisions a naming violation rather than a runtime surprise, and lint can enforce the syntax.</li><li>Two doors are deliberately left open for downstream decisions: key registries (enumerating well-known keys per system) and a separate selectable field for systems that operate a selector engine. Neither changes this spec.</li></ul><h2 id="links" tabindex="-1">Links <a class="header-anchor" href="#links" aria-label="Permalink to &quot;Links&quot;">​</a></h2><ul><li><a href="https://kubernetes.io/docs/concepts/overview/working-with-objects/labels/" target="_blank" rel="noreferrer">Kubernetes: Labels and Selectors</a></li><li><a href="https://kubernetes.io/docs/concepts/overview/working-with-objects/annotations/" target="_blank" rel="noreferrer">Kubernetes: Annotations</a></li><li><a href="https://github.com/cloudevents/spec" target="_blank" rel="noreferrer">CloudEvents specification</a></li></ul>`,40)])])}const m=t(i,[["render",r]]);export{u as __pageData,m as default};
